package bundled

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/easydev-org/easyagent/agent"
	"github.com/easydev-org/easyagent/llm"
	"github.com/easydev-org/easyagent/store"
)

// StoreDeps is the host-capability implementation backed by the store + a blob
// reader/writer + the provider registry. It is what agent-go injects into the
// in-process bundled extension (the equivalent of the TS `BundledDeps`).
type StoreDeps struct {
	DB *store.DB
	// BlobGet reads stored file bytes; BlobPut stores generated bytes.
	BlobGetFn func(tenant, code string) (map[string]any, []byte, bool)
	BlobPutFn func(ctx context.Context, tenant, code string, data []byte) error
	// Config resolves a tenant config knob (the agent's `cfg` KV view).
	ConfigFn func(tenant, key string) (string, bool)
	// SessionVar reads a projected session variable (e.g. locale).
	SessionVarFn func(tenant, session, name string) (string, bool)
	// Mail publishes a mailbox message (bus when wired, else the store queue).
	MailFn func(tenant, session, typ string, payload any, source string) error
	// OnIngest is called after a generated blob is stored (e.g. media probe).
	OnIngestFn func(ctx context.Context, tenant, code, name, mime string, data []byte)
}

// SessionVariable implements Deps.
func (d *StoreDeps) SessionVariable(tenant, session, name string) (string, bool) {
	if d.SessionVarFn == nil {
		return "", false
	}
	return d.SessionVarFn(tenant, session, name)
}

// ResolveConfig implements Deps (session override → global).
func (d *StoreDeps) ResolveConfig(name, session, tenant string) string {
	if d.ConfigFn == nil {
		return ""
	}
	if session != "" {
		if v, ok := d.ConfigFn(tenant, "session."+session+"."+name); ok && v != "" {
			return v
		}
	}
	if v, ok := d.ConfigFn(tenant, name); ok {
		return v
	}
	return ""
}

// ResolveTextModel implements Deps (a `provider/model` ref → v4 client + model).
func (d *StoreDeps) ResolveTextModel(tenant, ref string) (*llm.Client, string, error) {
	prov, model, err := d.providerFor(tenant, ref, "text")
	if err != nil {
		return nil, "", err
	}
	return llm.New(llm.ProviderCredentials{
		ProviderID: prov.ProviderID, BaseURL: prov.BaseURL, APIKey: prov.APIKey,
		Headers: headers(prov.Headers),
	}, nil), model, nil
}

// ResolveGenerative implements Deps (a capability-tagged `provider/model` ref).
func (d *StoreDeps) ResolveGenerative(capability, ref, tenant string) (*llm.Client, string, error) {
	prov, model, err := d.providerFor(tenant, ref, capability)
	if err != nil {
		return nil, "", err
	}
	return llm.New(llm.ProviderCredentials{
		ProviderID: prov.ProviderID, BaseURL: prov.BaseURL, APIKey: prov.APIKey,
		Headers: headers(prov.Headers),
	}, nil), model, nil
}

// providerFor resolves a `provider/model` ref to a provider row + model id,
// validating the provider's capability (semantic grouping).
func (d *StoreDeps) providerFor(tenant, ref, capability string) (store.Provider, string, error) {
	providerID, modelID, ok := splitRef(ref)
	if !ok {
		return store.Provider{}, "", fmt.Errorf("no model selected — set a %s model as \"provider_id/model_id\" (got %q)", capability, ref)
	}
	rows, err := d.DB.ListProviders(tenant)
	if err != nil {
		return store.Provider{}, "", err
	}
	for _, p := range rows {
		if p.ProviderID != providerID {
			continue
		}
		if c := p.Capability; c != "" && c != capability {
			return store.Provider{}, "", fmt.Errorf("provider %q serves %q, not %q", providerID, c, capability)
		}
		return p, modelID, nil
	}
	return store.Provider{}, "", fmt.Errorf("provider not found: %s", providerID)
}

// BlobGet implements Deps.
func (d *StoreDeps) BlobGet(tenant, code string) (map[string]any, []byte, bool) {
	if d.BlobGetFn == nil {
		return nil, nil, false
	}
	return d.BlobGetFn(tenant, code)
}

// IngestBlob implements Deps.
func (d *StoreDeps) IngestBlob(tenant, session, name string, data []byte) (string, string, string, error) {
	code := newCode()
	mime := sniffMime(data)
	if d.BlobPutFn != nil {
		if err := d.BlobPutFn(context.Background(), tenant, code, data); err != nil {
			return "", "", "", err
		}
	}
	_, _ = d.DB.UpsertFile(store.AgentFile{
		Code: code, Tenant: tenant, SHA256: sha256Hex(data), Name: name,
		Mime: mime, Size: int64(len(data)), UploaderSession: session,
	})
	if d.OnIngestFn != nil {
		d.OnIngestFn(context.Background(), tenant, code, name, mime, data)
	}
	return code, mime, name, nil
}

// SessionGroup implements Deps.
func (d *StoreDeps) SessionGroup(tenant, sid string) string {
	s, ok, _ := d.DB.GetSession(tenant, sid)
	if !ok {
		return ""
	}
	return s.Group
}

// SessionExists implements Deps.
func (d *StoreDeps) SessionExists(tenant, sid string) bool {
	ok, _ := d.DB.SessionExists(tenant, sid)
	return ok
}

// SessionTip implements Deps.
func (d *StoreDeps) SessionTip(tenant, sid string) string {
	t, _ := d.DB.SessionTip(tenant, sid)
	return t
}

// SessionsInGroup implements Deps.
func (d *StoreDeps) SessionsInGroup(tenant, group string) []string {
	rows, _ := d.DB.Children(tenant, group)
	out := make([]string, 0, len(rows))
	for _, r := range rows {
		out = append(out, r.Name)
	}
	return out
}

// ForkSession implements Deps (O(1) fork: copy inheritable cols, share the tip).
func (d *StoreDeps) ForkSession(tenant, parent, child string) error {
	p, ok, err := d.DB.GetSession(tenant, parent)
	if err != nil {
		return err
	}
	if !ok {
		return fmt.Errorf("parent session not found: %s", parent)
	}
	return d.DB.CreateSession(tenant, store.SessionInput{
		Name: child, Model: p.Model, Variant: p.Variant, Preset: p.Preset,
		TipID: p.TipID, SystemPrompt: p.SystemPrompt, MaxTurns: p.MaxTurns,
		Locale: p.Locale, Group: parent, // group = parent's name
	})
}

// DeleteSessionRow implements Deps.
func (d *StoreDeps) DeleteSessionRow(tenant, sid string) error {
	return d.DB.DeleteSession(tenant, sid)
}

// DeleteSessionMailbox implements Deps.
func (d *StoreDeps) DeleteSessionMailbox(tenant, sid string) error {
	return d.DB.DeleteSession(tenant, sid) // DeleteSession already purges the queue
}

// PublishMailbox implements Deps.
func (d *StoreDeps) PublishMailbox(tenant, session, typ string, payload any, source string) error {
	if d.MailFn != nil {
		return d.MailFn(tenant, session, typ, payload, source)
	}
	_, err := d.DB.Enqueue(tenant, session, typ, payload, source)
	return err
}

// MessageChain implements Deps (oldest-first; limit <= 0 = no cap).
func (d *StoreDeps) MessageChain(tenant, tip string, limit int) []ChainEntry {
	if limit <= 0 {
		limit = 1_000_000 // effectively uncapped
	}
	msgs, err := d.DB.Chain(tenant, tip, limit, "")
	if err != nil {
		return nil
	}
	out := make([]ChainEntry, 0, len(msgs))
	// Chain returns oldest-first; depth 0 = tip, so depth = len-1-i.
	for i, m := range msgs {
		out = append(out, ChainEntry{
			ID: m.ID, Role: m.Role, CreatedAt: m.CreatedAt,
			Depth: len(msgs) - 1 - i, Source: m.Source,
		})
	}
	return out
}

// MessageParts implements Deps.
func (d *StoreDeps) MessageParts(tenant string, ids []string) []MessagePartRow {
	parts, err := d.DB.PartsByMessages(tenant, ids)
	if err != nil {
		return nil
	}
	out := make([]MessagePartRow, 0, len(parts))
	for _, p := range parts {
		out = append(out, MessagePartRow{MessageID: p.MessageID, Type: p.Type, Seq: p.Seq, Data: p.Data})
	}
	return out
}

// TodosReplace implements Deps.
func (d *StoreDeps) TodosReplace(tenant, sid string, rows []TodoRow) error {
	return d.DB.TodosReplace(tenant, sid, toStoreTodos(rows))
}

func toStoreTodos(rows []TodoRow) []struct {
	Content  string
	Status   string
	Priority string
} {
	out := make([]struct {
		Content  string
		Status   string
		Priority string
	}, 0, len(rows))
	for _, r := range rows {
		out = append(out, struct {
			Content  string
			Status   string
			Priority string
		}{r.Content, r.Status, r.Priority})
	}
	return out
}

var _ agent.ToolRegistry = (*Extension)(nil)

func splitRef(ref string) (string, string, bool) {
	i := strings.IndexByte(ref, '/')
	if i <= 0 || i == len(ref)-1 {
		return "", "", false
	}
	return ref[:i], ref[i+1:], true
}

func headers(raw string) map[string]string {
	if raw == "" || raw == "null" {
		return nil
	}
	m := map[string]string{}
	if err := json.Unmarshal([]byte(raw), &m); err != nil {
		return nil
	}
	return m
}

func sha256Hex(data []byte) string {
	h := sha256.Sum256(data)
	return hex.EncodeToString(h[:])
}

// newCode mints a 16-char content code (the `file:<code>` segment).
func newCode() string {
	var b [8]byte
	_, _ = rand.Read(b[:])
	return hex.EncodeToString(b[:])
}

// sniffMime derives a content type from the leading bytes.
func sniffMime(b []byte) string {
	switch {
	case len(b) >= 8 && string(b[:8]) == "\x89PNG\r\n\x1a\n":
		return "image/png"
	case len(b) >= 3 && b[0] == 0xFF && b[1] == 0xD8 && b[2] == 0xFF:
		return "image/jpeg"
	case len(b) >= 6 && (string(b[:6]) == "GIF87a" || string(b[:6]) == "GIF89a"):
		return "image/gif"
	case len(b) >= 12 && string(b[4:8]) == "ftyp":
		return "video/mp4"
	case len(b) >= 4 && string(b[:4]) == "RIFF":
		return "audio/wav"
	case len(b) >= 4 && string(b[:4]) == "OggS":
		return "audio/ogg"
	case len(b) >= 3 && string(b[:3]) == "ID3":
		return "audio/mpeg"
	case len(b) >= 2 && b[0] == 0xFF && (b[1]&0xE0) == 0xE0:
		return "audio/mpeg"
	default:
		return "application/octet-stream"
	}
}
